// try / catch / finally の流れを確かめる
// ここを変えてみよう:inputs に "-5" や " 7" や null を足す / finally の行を消してみる
String[] inputs = {"12", "12a", "", "0"};

for (String input : inputs) {
    System.out.println("--- 入力: \"" + input + "\"");
    try {
        int qty = Integer.parseInt(input);   // 失敗するとここで中断
        System.out.println("数量: " + qty);
        System.out.println("1個あたり: " + (1200 / qty) + "円");
    } catch (NumberFormatException e) {
        System.out.println("数値ではありません → " + e.getMessage());
    } catch (ArithmeticException e) {
        System.out.println("0 では割れません → " + e.getMessage());
    } finally {
        System.out.println("(チェック終了)");   // 例外の有無にかかわらず必ず実行
    }
}

// 独自例外を throw して、呼び出し側で catch する
// ここを変えてみよう:order の数量を 3 / 10 / 0 に変える
class StockShortageException extends Exception {     // Exception を継承 = 検査例外
    StockShortageException(String message) {
        super(message);
    }
}

class Inventory {
    private int stock = 5;

    // 検査例外を投げるメソッドは throws で宣言する(消すとコンパイルエラー)
    void ship(String item, int qty) throws StockShortageException {
        if (qty < 1) {
            // 前提違反は非検査例外で
            throw new IllegalArgumentException("数量は1以上: " + qty);
        }
        if (qty > stock) {
            throw new StockShortageException(
                item + " の在庫不足(要求 " + qty + " / 在庫 " + stock + ")");
        }
        stock -= qty;
        System.out.println(item + " を " + qty + " 個出荷。残り " + stock);
    }
}

Inventory inv = new Inventory();
int[] orders = {3, 4, 0};
for (int qty : orders) {
    try {
        inv.ship("トナー", qty);
    } catch (StockShortageException e) {
        System.out.println("[業務エラー] " + e.getMessage());
    } catch (IllegalArgumentException e) {
        System.out.println("[入力エラー] " + e.getMessage());
    }
}

// try-with-resources:AutoCloseable を実装すると自動で close される
// ここを変えてみよう:fail を true にする / リソースを3つに増やして close の順番を見る
class Res implements AutoCloseable {
    private final String name;
    Res(String name) {
        this.name = name;
        System.out.println("open  " + name);
    }
    @Override
    public void close() {                 // throws を付けなければ catch 不要
        System.out.println("close " + name);
    }
}

boolean fail = false;
try (Res db = new Res("DB接続");
     Res file = new Res("ファイル")) {
    System.out.println("処理中…");
    if (fail) {
        throw new IllegalStateException("処理失敗");
    }
} catch (IllegalStateException e) {
    // close は catch より「前」に終わっている
    System.out.println("catch " + e.getMessage());
} finally {
    System.out.println("finally");
}

// ラップして再スロー:cause を渡すと「本当の原因」が残る
// ここを変えてみよう:text を "8080" にする / new ConfigException の第2引数 e を消してみる
class ConfigException extends RuntimeException {
    ConfigException(String message, Throwable cause) {
        super(message, cause);
    }
}

int readPort(String text) {
    try {
        return Integer.parseInt(text);
    } catch (NumberFormatException e) {
        // 自分の層に合った例外に包み直す。e(原因)を必ず渡す
        throw new ConfigException("ポート番号が不正: " + text, e);
    }
}

String text = "80a";
try {
    System.out.println("ポート: " + readPort(text));
} catch (ConfigException e) {
    System.out.println("例外    : " + e.getMessage());
    System.out.println("Caused by: " + e.getCause());
}

